arguments.command:
for f in observed_run/debug/*.json; do echo "=== $f ==="; python3 -c "
import json, sys
data = json.load(open('$f'))
if isinstance(data, dict):
    keys = list(data.keys())
    print('keys:', keys)
    for k in keys[:10]:
        v = data[k]
        if isinstance(v, (int,float)):
            print(f'  {k}: {v}')
        elif isinstance(v, list) and all(isinstance(x,(int,float)) for x in v[:5]):
            print(f'  {k}: len={len(v)}, first5={v[:5]}')
        elif isinstance(v, str):
            print(f'  {k}: {v[:200]}')
        else:
            print(f'  {k}: type={type(v).__name__}')
"; echo; done

